        json_data[f'row_{i}'] = row
    return json.dumps(json_data)

def csv_file_to_json(file_path):
    with open(file_path, 'r') as file:
        csv_reader = csv.reader(file)
        csv_data = list(csv_reader)
    return csv_to_json(csv_data)

