def csv_to_json(csv_data):
    """
    Convert CSV data into a JSON string.

    Args:
        csv_data (list): A 2D list representing the CSV data.

    Returns:
        str: A JSON string representing the CSV data.
    """
    json_data = {}
    for i, row in enumerate(csv_data):
        json_data[f'row_{i}'] = row
    return json.dumps(json_data)
